/**
 * Level data. Maps are ASCII (1 char = 1 tile), generated by tools/build_demo_map.py (Easy),
 * tools/build_medium_map.py (Medium) and tools/build_hard_map.py (Hard), where the design notes live. Tables hold what a map can't say.
 *   #  solid ground          P  player spawn          K  checkpoint        E  exit
 *   C  Clicker (post, faces left)   N  Clicker (post, faces right)   c  Clicker (patrols)
 *   R  Runner                S  Screamer (faces left) H  horde Clicker, feeding on the corpses
 *   x  bottle stash          B  cover crate (crouch behind it to hide)
 *   D  locked door (bottom tile, 3 tall; keys from `guardians`, `doorKeys` for more than 1)
 *   G  horde gate (bottom tile, 3 tall): opens when every horde zombie is dead
 *   V  the wrecked car (Molotov)    X  corpse (decor)    L  the father's letter
 *   b  box (decor)           o  stone (decor)
 *   W  big crate (cover, Mechanic 2)   A  tent (decor)   F  campfire (decor)
 *   J  the dead soldier and his newspaper (Mechanic 2's guide)
 *   Z  wooden scaffolding: solid to walk on, but snipers see and shoot through it
 *   Q  concrete block (cover that never breaks)   Y  army ammo crate (the smoke grenades, M2 Medium)
 */

import type { HeliDef } from './Helicopter';
import { SniperKind, type SniperDef } from './Sniper';
import { Part, Upgrade } from './Upgrades';

/** Coloured keys (Medium): the car trunk's three padlocks. */
export enum KeyColor {
  Red,
  Green,
  Blue,
  Count,
}

/** Zombies (tile x, y in the map) that together carry one coloured key: it drops when all are dead. */
export interface KeyGroup {
  color: KeyColor;
  zombies: [number, number][];
}

/**
 * What a death must not undo (passed through scene.restart): coloured keys, the Molotov story.
 * Zombies whose key already dropped stay dead; a dropped key lies where it fell until picked up.
 */
export class LevelProgress {
  keyDropped: boolean[] = [false, false, false]; // indexed by KeyColor
  keyHeld: boolean[] = [false, false, false];
  keyX: number[] = [0, 0, 0]; // where a dropped key lies (px, feet)
  keyY: number[] = [0, 0, 0];
  keysUsed = false; // the trunk took them
  carStage = 0; // 0 never looked, 1 looked (before the horde), 2 knows the plan, 3 trunk open
  sawHorde = false;
  rag = false;
  molotov = false; // crafted
  hordeBurned = false;
  introSeen = false; // the level's opening thoughts (shown once, not again after a death)
  sawGunner = false; // M2 Medium: has seen the machine gun's ground (the ammo crate now matters)
  cacheLooted = false;
  smokes = 0; // smoke grenades in hand
  crateHp: number[] = []; // M2 Medium: each breakable crate's hits left (by spawn order); damage survives a death
  smokesAtCheckpoint = -1; // M2 Hard: smoke grenades held at the last checkpoint (-1: none passed yet)
  parts: number[] = new Array<number>(Part.Count).fill(0); // Mechanic 3: parts in hand, indexed by Part
  partsTaken: number[] = []; // Mechanic 3: pickups already taken (spawn order), gone after a death too
  built: boolean[] = new Array<boolean>(Upgrade.Count).fill(false); // Mechanic 3: upgrades built on this visit
}

export interface LevelData {
  map: string[];
  guardians: [number, number][]; // each carries one door key (for 'D')
  doorKeys: [number, number, number][]; // doors that take more than one key: tile x, y, keys
  keyGroups: KeyGroup[];
  night: boolean; // darkness, clicks, lightning + thunder (Blackout.ts)
  stashSize: number; // bottles per stash, 0 = the throw tuning's default
  grantsListen: boolean; // Listen Mode from the start; finishing the level unlocks it everywhere
  intro: string[]; // the survivor's thoughts when the level starts (Arabic)
  introBanner: string;
  hints: [number, number, string][]; // world text: tile x, y (centre), text
  cheats: boolean; // key 1 toggles: unlimited bottles / smoke + invisible (zombies and soldiers) + every door open
  snipers: SniperDef[]; // Mechanic 2: soldiers on towers and roofs
  breakableCrates: boolean; // big wooden crates ('W') break after CRATE_HP hits
  gunnerSeenAt: number; // tile x: walking past it the player sees the machine gun (smoke quest), 0 = none
  revealed: [number, number][]; // scaffolding tiles that appear once the machine gun has been seen
  heli: HeliDef | null; // M2 Hard: the helicopter that hunts you down the valley
  startSmokes: number; // smoke grenades in hand at the start
  upgrades: Upgrade[]; // Mechanic 3: what the workbench builds (non-empty: parts, bench and built upgrades work here)
  grants: Upgrade[]; // Mechanic 3: upgrades you have here even if never built (from an earlier level)
  pillTime: number; // Mechanic 3: s of breath from one breath pill (and from each air pocket); 0 = no pills here
}

